@extends('layouts.app') @section('content')<h1>Ajuste de inventario</h1><p class="muted">Registra la cantidad física contada. Los productos empacados se cuentan por piezas completas; los productos a granel permiten fracciones.</p><form class="card" method="post" action="{{ route('inventory.adjust') }}">@csrf <input name="reason" placeholder="Motivo del ajuste" required><div style="overflow-x:auto"><table><tr><th>Producto</th><th>Existencia actual</th><th>Nueva cantidad física</th></tr>@foreach($products as $i=>$product)<tr><td>{{ $product->name }}<br><small class="muted">{{ $product->unit->name }} · {{ $product->unit->allows_decimal ? 'Admite fracciones' : 'Solo unidades enteras' }}</small><input type="hidden" name="items[{{ $i }}][product_id]" value="{{ $product->id }}"></td><td>{{ $product->unit->formatQuantity($product->inventory->quantity) }} {{ $product->unit->abbreviation }}</td><td><input name="items[{{ $i }}][quantity_after]" type="number" step="{{ $product->unit->allows_decimal ? '.001' : '1' }}" min="0" value="{{ $product->inventory->quantity }}"></td></tr>@endforeach</table></div><button>Confirmar ajuste</button></form>@endsection
